const tableName = "!campfirechat";
const table = game.tables.getName(tableName);

if (!table) {
  ui.notifications.warn(`Rolltable "${tableName}" not found.`);
} else {
  // Roll silently on the table
  const roll = await table.draw({ displayChat: false });

  // Format the output box
  const flavorText = `
    <div style="
      background-color:#1d1c1a;
      border: 2px solid #5f574e;
      box-shadow: 3px 3px 10px rgba(0, 0, 0, 0.6);
      border-radius: 12px;
      padding: 16px;
      color: #e4ddc7;
      font-family: 'serif';
      max-width: 500px;
      margin: auto;
    ">
      <div style="text-align: center; margin-bottom: 10px;">
        <img src="assets/images/campfire-chat.webp" width="80" height="80" style="border: none;">
      </div>
      <div style="text-align: center; font-weight: bold; font-size: 16px; letter-spacing: 1px; color: #c7b26f; margin-bottom: 12px;">
        CAMPFIRE CHAT
      </div>
      <div style="font-size: 14px; font-style: italic; margin-bottom: 12px;">
        The fire crackles against the dark.<br>Beyond the ring of warmth: darkness, silence and stone.<br><br>
        <strong style="color: #e4ddc7;">"In the flame’s warm glow, answer this..."</strong>
      </div>
      <hr style="border: 1px solid #5f574e;">
      <div style="font-size: 16px; text-align: center; font-style: italic; margin: 12px 0;">
        ${roll.results[0].text}
      </div>
      <hr style="border: 1px solid #5f574e;">
      <div style="font-size: 12px; font-style: italic; text-align: center; color: #a09888; margin-top: 6px;">
        The question lingers, heavy as the stone beneath your boots.
      </div>
    </div>
  `;

  // Send to chat as a public message
  ChatMessage.create({
    content: flavorText
  });
}
